/**
 * Region `oban`, "Oban and Lorn": the first region made from real map data by the coast
 * pipeline (tools/coast; docs/COAST_PIPELINE.md): Kerrera and its sound, Oban Bay,
 * Dunollie, Ganavan, Dunstaffnage and Connel at full scale, from OpenStreetMap and
 * OpenSeaMap, Copernicus heights, EMODnet depths and ESA land cover. Its data is the
 * pipeline's package (oban.coast.json, regenerated by `npm run build` in tools/coast); its
 * ground is the package's mesh, fetched at start.
 *
 * Where: a debug toggle (regions/index.ts) puts it in place of the Sounds, north of home,
 * with the south entrance of Kerrera Sound due north of Calder Haven (the way you would come
 * in from the south). At full scale it is 11.7 x 11.1 km, so it also covers where the Fjord
 * lies: the Fjord is left out while it's on. The Narrows stay, to the west.
 *
 * The weather is the Sounds' (rough, fog and drizzle common): the request's north-rough.
 */
import type { CoastPackage } from '../coastRegion';
import { fromCoastPackage } from '../coastRegion';
import { SOUNDS } from './sounds';
import pkg from './oban.coast.json';

export const OBAN = fromCoastPackage(pkg as unknown as CoastPackage, {
  // The package's origin (the box's centre) in the world: Kerrera Sound's south entrance
  // (about x -4400 in the package) north of Calder Haven (x 570), the box's south edge at
  // z -1900 where the Sounds' was (its box runs to z 5560 in the package).
  x: 4970,
  z: -7460,
  weather: SOUNDS.weather,
});
